// MCP tool descriptors. Each pairs a schema with a tool name and description
// so that LLM clients can discover and invoke the underlying RPCs.
var (
	Events_BatchGetEventsTool = newTool("events-batch_get_events_v1", `Retrieves several events by name in one call. GET /v1/{parent=calendars/*}/events:batchGet CALDAV:calendar-multiget, RFC 4791 section 7.9 <https://www.rfc-editor.org/rfc/rfc4791.html#section-7.9>: a client that has synchronised a collection holds hrefs and wants the bodies, which is one round trip here instead of one GET per event. Safe and idempotent. Events come back in the order requested, per AIP-231 <https://aip.dev/231>. All-or-nothing: an unreadable or missing name fails the whole call rather than returning a short list, so a caller never has to work out which name a gap belonged to. NOT_FOUND          any requested event does not exist INVALID_ARGUMENT   a name is malformed, sits under a different parent, or the list is empty or over 1000 PERMISSION_DENIED  caller may not read any one of them`, Events_BatchGetEventsSchemaJSON, Events_BatchGetEventsOutputSchemaJSON, nil, "", nil)
	Events_CreateEventTool    = newTool("events-create_event_v1", `Creates a event. POST /v1/{parent=calendars/*}/events body: the event itself Server-assigned fields on the request body are ignored: `+"`"+`name`+"`"+`, `+"`"+`uid`+"`"+`, `+"`"+`etag`+"`"+` and the timestamps are set by the server regardless of what is sent. Supply `+"`"+`event_id`+"`"+` to choose the final path segment; leave it empty and the server generates one. Not idempotent. Retrying after a timeout may create a second event; supply `+"`"+`event_id`+"`"+` if the caller needs retry safety. ALREADY_EXISTS     that event_id is taken INVALID_ARGUMENT   a field violates its buf.validate constraint PERMISSION_DENIED  caller may not create here`, Events_CreateEventSchemaJSON, Events_CreateEventOutputSchemaJSON, nil, "", nil)
	Events_DeleteEventTool    = newTool("events-delete_event_v1", `Deletes a event. DELETE /v1/{name=calendars/*/events/*} Soft delete: the event is marked deleted, disappears from List unless `+"`"+`show_deleted`+"`"+` is set, and is purged at `+"`"+`expire_time`+"`"+`. Recover it with Undelete before then. Idempotent in effect but not in reporting: a second delete returns NOT_FOUND rather than succeeding silently. NOT_FOUND          no such event ABORTED            etag does not match PERMISSION_DENIED  caller may not delete it`, Events_DeleteEventSchemaJSON, Events_DeleteEventOutputSchemaJSON, nil, "", nil)
	Events_ExpandEventTool    = newTool("events-expand_event_v1", `Materialises the occurrences of a recurring event within a time window. POST /v1/{name=calendars/*/events/*}:expand body: the whole request message A custom method (AIP-136) because expansion cannot be generalised across resource types the way export can -- only a recurrence rule expands. The window is a google.type.Interval and is required at both ends, deliberately. A rule bounded by neither UNTIL nor COUNT generates infinitely many instances, so there is no safe default and a missing bound is a caller bug worth reporting rather than one the server guesses around. The interval is half-open: instances at `+"`"+`start_time`+"`"+` are included, instances at `+"`"+`end_time`+"`"+` are not. Returns materialised instances with EXDATE exclusions removed and RDATE additions folded in. None is a stored resource, so none carries a resource name and none can be passed to Get, Update or Delete -- edit the series through its stored event instead. Paginated like List, with its own `+"`"+`page_size`+"`"+` default of 250. NOT_FOUND          no such event INVALID_ARGUMENT   window.end_time is not after window.start_time FAILED_PRECONDITION  the event has no recurrence rule PERMISSION_DENIED  caller may not read it`, Events_ExpandEventSchemaJSON, Events_ExpandEventOutputSchemaJSON, nil, "", nil)
	Events_GetEventTool       = newTool("events-get_event_v1", `Retrieves one event. GET /v1/{name=calendars/*/events/*} Safe and idempotent. Returns the resource as stored; no field is computed per-caller. Read the `+"`"+`etag`+"`"+` here and pass it back on update or delete to make the write conditional. NOT_FOUND          no such event, or it is soft-deleted and `+"`"+`show_deleted`+"`"+` was not set INVALID_ARGUMENT   name does not match calendars/*/events/* PERMISSION_DENIED  caller may not read it`, Events_GetEventSchemaJSON, Events_GetEventOutputSchemaJSON, nil, "", nil)
	Events_ListEventsTool     = newTool("events-list_events_v1", `Lists events. GET /v1/{parent=calendars/*}/events Paginated per AIP-158: pass `+"`"+`page_size`+"`"+` (defaults to 50, capped at 1000) and the `+"`"+`next_page_token`+"`"+` from the previous response. An empty `+"`"+`next_page_token`+"`"+` means the last page. Page tokens are opaque and may expire; do not construct or store them. Filtering uses the AIP-160 expression language over the resource's own fields. Results carry no guaranteed order. Returns stored events, one per recurrence rule -- listing does not expand recurrences. An unbounded rule has infinitely many instances, so expansion needs a window and lives in ExpandEvent. INVALID_ARGUMENT   malformed filter, or page_size out of range PERMISSION_DENIED  caller may not list this collection`, Events_ListEventsSchemaJSON, Events_ListEventsOutputSchemaJSON, nil, "", nil)
	Events_UndeleteEventTool  = newTool("events-undelete_event_v1", `Restores a soft-deleted event. POST /v1/{name=calendars/*/events/*}:undelete Valid only before `+"`"+`expire_time`+"`"+`; after that the event is gone and this returns NOT_FOUND. Clears `+"`"+`delete_time`+"`"+` and `+"`"+`expire_time`+"`"+` and returns the event as it was. NOT_FOUND          no such event, or already purged ALREADY_EXISTS     the event is not deleted PERMISSION_DENIED  caller may not restore it`, Events_UndeleteEventSchemaJSON, Events_UndeleteEventOutputSchemaJSON, nil, "", nil)
	Events_UpdateEventTool    = newTool("events-update_event_v1", `Updates a event. PATCH /v1/{event.name=calendars/*/events/*} body: the event itself A partial update: only fields named in `+"`"+`update_mask`+"`"+` are written. An empty mask writes every mutable field, which will clear anything the caller left unset -- pass a mask unless that is the intent. OUTPUT_ONLY and IMMUTABLE fields are rejected rather than silently dropped. Idempotent. Pass the `+"`"+`etag`+"`"+` read from Get to make the write conditional. NOT_FOUND          no such event ABORTED            etag does not match the stored resource INVALID_ARGUMENT   mask names an unknown or immutable field PERMISSION_DENIED  caller may not modify it`, Events_UpdateEventSchemaJSON, Events_UpdateEventOutputSchemaJSON, nil, "", nil)
)

