// return (resp, error). Server-streaming RPCs (with MCPProgress) take (req,
// stream) matching the gRPC server interface — any type implementing
// EventsServer automatically satisfies this interface.
type EventsMCPServer interface {
	BatchGetEvents(ctx context.Context, req *v1.BatchGetEventsRequest) (*v1.BatchGetEventsResponse, error)
	CreateEvent(ctx context.Context, req *v1.CreateEventRequest) (*v1.Event, error)
	DeleteEvent(ctx context.Context, req *v1.DeleteEventRequest) (*emptypb.Empty, error)
	ExpandEvent(ctx context.Context, req *v1.ExpandEventRequest) (*v1.ExpandEventResponse, error)
	GetEvent(ctx context.Context, req *v1.GetEventRequest) (*v1.Event, error)
	ListEvents(ctx context.Context, req *v1.ListEventsRequest) (*v1.ListEventsResponse, error)
	UndeleteEvent(ctx context.Context, req *v1.UndeleteEventRequest) (*v1.Event, error)
	UpdateEvent(ctx context.Context, req *v1.UpdateEventRequest) (*v1.Event, error)
}

